-- Sarith/Rubak public v0 access, bind two original doors and clear one staff status.
-- Uses Rubak's checked stock safe tuple, plus the measured Sarith deck arrival.
DELIMITER $$
BEGIN NOT ATOMIC
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
    START TRANSACTION;
    IF (SELECT COUNT(*) FROM doors WHERE id=35222 AND SHA2(JSON_ARRAY(`id`,`doorid`,`zone`,`version`,`name`,`pos_y`,`pos_x`,`pos_z`,`heading`,`opentype`,`guild`,`lockpick`,`keyitem`,`nokeyring`,`triggerdoor`,`triggertype`,`disable_timer`,`doorisopen`,`door_param`,`dest_zone`,`dest_instance`,`dest_x`,`dest_y`,`dest_z`,`dest_heading`,`invert_state`,`incline`,`size`,`buffer`,`client_version_mask`,`is_ldon_door`,`close_timer_ms`,`dz_switch_id`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`),256)='6ea720e4743817cf34aed746d9169df225548dd54960b0c538acd0285fdb9991')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rubak public doors 35222 preimage mismatch'; END IF;
    IF (SELECT COUNT(*) FROM doors WHERE id=35518 AND SHA2(JSON_ARRAY(`id`,`doorid`,`zone`,`version`,`name`,`pos_y`,`pos_x`,`pos_z`,`heading`,`opentype`,`guild`,`lockpick`,`keyitem`,`nokeyring`,`triggerdoor`,`triggertype`,`disable_timer`,`doorisopen`,`door_param`,`dest_zone`,`dest_instance`,`dest_x`,`dest_y`,`dest_z`,`dest_heading`,`invert_state`,`incline`,`size`,`buffer`,`client_version_mask`,`is_ldon_door`,`close_timer_ms`,`dz_switch_id`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`),256)='d81f70e4c808d29e59dad8c7232b6a691f59df233a1d48f3a6dc80d7256a883b')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rubak public doors 35518 preimage mismatch'; END IF;
    IF (SELECT COUNT(*) FROM zone WHERE id=5868 AND SHA2(JSON_ARRAY(`id`,`zoneidnumber`,`version`,`short_name`,`long_name`,`min_status`,`map_file_name`,`note`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`,`expansion`,`file_name`,`safe_x`,`safe_y`,`safe_z`,`safe_heading`,`graveyard_id`,`min_level`,`max_level`,`timezone`,`maxclients`,`ruleset`,`underworld`,`minclip`,`maxclip`,`fog_minclip`,`fog_maxclip`,`fog_blue`,`fog_red`,`fog_green`,`sky`,`ztype`,`zone_exp_multiplier`,`walkspeed`,`time_type`,`fog_red1`,`fog_green1`,`fog_blue1`,`fog_minclip1`,`fog_maxclip1`,`fog_red2`,`fog_green2`,`fog_blue2`,`fog_minclip2`,`fog_maxclip2`,`fog_red3`,`fog_green3`,`fog_blue3`,`fog_minclip3`,`fog_maxclip3`,`fog_red4`,`fog_green4`,`fog_blue4`,`fog_minclip4`,`fog_maxclip4`,`fog_density`,`flag_needed`,`canbind`,`cancombat`,`canlevitate`,`castoutdoor`,`hotzone`,`insttype`,`shutdowndelay`,`peqzone`,`bypass_expansion_check`,`suspendbuffs`,`rain_chance1`,`rain_chance2`,`rain_chance3`,`rain_chance4`,`rain_duration1`,`rain_duration2`,`rain_duration3`,`rain_duration4`,`snow_chance1`,`snow_chance2`,`snow_chance3`,`snow_chance4`,`snow_duration1`,`snow_duration2`,`snow_duration3`,`snow_duration4`,`gravity`,`type`,`skylock`,`fast_regen_hp`,`fast_regen_mana`,`fast_regen_endurance`,`npc_max_aggro_dist`,`client_update_range`,`underworld_teleport_index`,`lava_damage`,`min_lava_damage`,`idle_when_empty`,`seconds_before_idle`,`shard_at_player_count`,`allow_mercs`),256)='66a1b3717bc7dcee4ad59823e87aad6806f927d8b0bc0dedf74c623e189d6309')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rubak public zone 5868 preimage mismatch'; END IF;
    IF (SELECT COUNT(*) FROM zone WHERE id=5867 AND SHA2(JSON_ARRAY(`id`,`zoneidnumber`,`version`,`short_name`,`long_name`,`min_status`,`map_file_name`,`note`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`,`expansion`,`file_name`,`safe_x`,`safe_y`,`safe_z`,`safe_heading`,`graveyard_id`,`min_level`,`max_level`,`timezone`,`maxclients`,`ruleset`,`underworld`,`minclip`,`maxclip`,`fog_minclip`,`fog_maxclip`,`fog_blue`,`fog_red`,`fog_green`,`sky`,`ztype`,`zone_exp_multiplier`,`walkspeed`,`time_type`,`fog_red1`,`fog_green1`,`fog_blue1`,`fog_minclip1`,`fog_maxclip1`,`fog_red2`,`fog_green2`,`fog_blue2`,`fog_minclip2`,`fog_maxclip2`,`fog_red3`,`fog_green3`,`fog_blue3`,`fog_minclip3`,`fog_maxclip3`,`fog_red4`,`fog_green4`,`fog_blue4`,`fog_minclip4`,`fog_maxclip4`,`fog_density`,`flag_needed`,`canbind`,`cancombat`,`canlevitate`,`castoutdoor`,`hotzone`,`insttype`,`shutdowndelay`,`peqzone`,`bypass_expansion_check`,`suspendbuffs`,`rain_chance1`,`rain_chance2`,`rain_chance3`,`rain_chance4`,`rain_duration1`,`rain_duration2`,`rain_duration3`,`rain_duration4`,`snow_chance1`,`snow_chance2`,`snow_chance3`,`snow_chance4`,`snow_duration1`,`snow_duration2`,`snow_duration3`,`snow_duration4`,`gravity`,`type`,`skylock`,`fast_regen_hp`,`fast_regen_mana`,`fast_regen_endurance`,`npc_max_aggro_dist`,`client_update_range`,`underworld_teleport_index`,`lava_damage`,`min_lava_damage`,`idle_when_empty`,`seconds_before_idle`,`shard_at_player_count`,`allow_mercs`),256)='4d4616dce7b1e13c27d544a9061ddc0a49acf3298fa4d2bc3c468a36e592a58f')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rubak public zone 5867 preimage mismatch'; END IF;
    IF EXISTS (SELECT 1 FROM zone_points WHERE zone='rubak' OR target_zone_id=727) OR EXISTS (SELECT 1 FROM doors WHERE dest_zone='rubak') OR EXISTS (SELECT 1 FROM dynamic_zone_templates WHERE zone_id=727) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rubak public route or expedition scope mismatch'; END IF;
    UPDATE doors SET dest_zone='rubak', dest_x=-61.83, dest_y=-1.71, dest_z=525, dest_heading=237 WHERE id=35222 AND SHA2(JSON_ARRAY(`id`,`doorid`,`zone`,`version`,`name`,`pos_y`,`pos_x`,`pos_z`,`heading`,`opentype`,`guild`,`lockpick`,`keyitem`,`nokeyring`,`triggerdoor`,`triggertype`,`disable_timer`,`doorisopen`,`door_param`,`dest_zone`,`dest_instance`,`dest_x`,`dest_y`,`dest_z`,`dest_heading`,`invert_state`,`incline`,`size`,`buffer`,`client_version_mask`,`is_ldon_door`,`close_timer_ms`,`dz_switch_id`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`),256)='6ea720e4743817cf34aed746d9169df225548dd54960b0c538acd0285fdb9991';
    IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rubak public doors 35222 affected count mismatch'; END IF;
    UPDATE doors SET dest_zone='sarithcity', dest_x=-1204, dest_y=-1159, dest_z=25, dest_heading=128 WHERE id=35518 AND SHA2(JSON_ARRAY(`id`,`doorid`,`zone`,`version`,`name`,`pos_y`,`pos_x`,`pos_z`,`heading`,`opentype`,`guild`,`lockpick`,`keyitem`,`nokeyring`,`triggerdoor`,`triggertype`,`disable_timer`,`doorisopen`,`door_param`,`dest_zone`,`dest_instance`,`dest_x`,`dest_y`,`dest_z`,`dest_heading`,`invert_state`,`incline`,`size`,`buffer`,`client_version_mask`,`is_ldon_door`,`close_timer_ms`,`dz_switch_id`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`),256)='d81f70e4c808d29e59dad8c7232b6a691f59df233a1d48f3a6dc80d7256a883b';
    IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rubak public doors 35518 affected count mismatch'; END IF;
    UPDATE zone SET min_status=0 WHERE id=5868 AND SHA2(JSON_ARRAY(`id`,`zoneidnumber`,`version`,`short_name`,`long_name`,`min_status`,`map_file_name`,`note`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`,`expansion`,`file_name`,`safe_x`,`safe_y`,`safe_z`,`safe_heading`,`graveyard_id`,`min_level`,`max_level`,`timezone`,`maxclients`,`ruleset`,`underworld`,`minclip`,`maxclip`,`fog_minclip`,`fog_maxclip`,`fog_blue`,`fog_red`,`fog_green`,`sky`,`ztype`,`zone_exp_multiplier`,`walkspeed`,`time_type`,`fog_red1`,`fog_green1`,`fog_blue1`,`fog_minclip1`,`fog_maxclip1`,`fog_red2`,`fog_green2`,`fog_blue2`,`fog_minclip2`,`fog_maxclip2`,`fog_red3`,`fog_green3`,`fog_blue3`,`fog_minclip3`,`fog_maxclip3`,`fog_red4`,`fog_green4`,`fog_blue4`,`fog_minclip4`,`fog_maxclip4`,`fog_density`,`flag_needed`,`canbind`,`cancombat`,`canlevitate`,`castoutdoor`,`hotzone`,`insttype`,`shutdowndelay`,`peqzone`,`bypass_expansion_check`,`suspendbuffs`,`rain_chance1`,`rain_chance2`,`rain_chance3`,`rain_chance4`,`rain_duration1`,`rain_duration2`,`rain_duration3`,`rain_duration4`,`snow_chance1`,`snow_chance2`,`snow_chance3`,`snow_chance4`,`snow_duration1`,`snow_duration2`,`snow_duration3`,`snow_duration4`,`gravity`,`type`,`skylock`,`fast_regen_hp`,`fast_regen_mana`,`fast_regen_endurance`,`npc_max_aggro_dist`,`client_update_range`,`underworld_teleport_index`,`lava_damage`,`min_lava_damage`,`idle_when_empty`,`seconds_before_idle`,`shard_at_player_count`,`allow_mercs`),256)='66a1b3717bc7dcee4ad59823e87aad6806f927d8b0bc0dedf74c623e189d6309';
    IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rubak public zone 5868 affected count mismatch'; END IF;
    COMMIT;
END$$
DELIMITER ;
